#include <bits/stdc++.h>
#define MAXNODES 5000010
#define INF_VAL 1000000000
#define IDX(x,k) (x+(k-1)*n)
using namespace std;
template<typename T> void read_value(T &x)
{
    x=0; char c=getchar(); bool neg=false;
    while(!isdigit(c)){if(c=='-') neg=true; c=getchar();}
    while(isdigit(c)){x=(x<<1)+(x<<3)+(c^48); c=getchar();}
    if(neg) x=-x;
}
int n,m,k,v1,v2,s,t;
int dist_arr[MAXNODES];
bool visited_arr[MAXNODES];
struct EdgeStruct
{
    int to,next,v,cost;
}edge_array[MAXNODES];
int head_array[MAXNODES],edge_idx=1;
void insert_edge(int from,int to,int val,int cost)
{
    edge_array[++edge_idx]=(EdgeStruct){to,head_array[from],val,cost}; head_array[from]=edge_idx;
    edge_array[++edge_idx]=(EdgeStruct){from,head_array[to],0,-cost}; head_array[to]=edge_idx;
}
bool shortest_path()
{
    queue<int> q;
    for(int i=s;i<=t;++i) dist_arr[i]=INF_VAL,visited_arr[i]=false;
    q.push(s); dist_arr[s]=0; visited_arr[s]=true;
    while(!q.empty())
    {
        int x=q.front(); q.pop(); visited_arr[x]=false;
        for(int i=head_array[x];i;i=edge_array[i].next)
        {
            int y=edge_array[i].to,c=edge_array[i].cost;
            if(dist_arr[y]<=dist_arr[x]+c||!edge_array[i].v) continue;
            dist_arr[y]=dist_arr[x]+c;
            if(!visited_arr[y]) {visited_arr[y]=true; q.push(y);}
        }
    }
    return dist_arr[t]!=INF_VAL;
}
int augment_flow(int x,int limit)
{
    if(x==t) return limit;
    visited_arr[x]=true;
    int flow_res=limit;
    for(int i=head_array[x];i;i=edge_array[i].next)
    {
        int y=edge_array[i].to,v=edge_array[i].v;
        if(dist_arr[y]!=dist_arr[x]+edge_array[i].cost||!v||visited_arr[y]) continue;
        if(int flow=augment_flow(y,min(flow_res,v)))
        {
            flow_res-=flow;
            edge_array[i].v-=flow;
            edge_array[i^1].v+=flow;
            if(!flow_res) break;
        }
    }
    return limit-flow_res;
}
int min_cost_flow()
{
    int total=0, flow;
    while(shortest_path())
        while(flow=augment_flow(s,INF_VAL))
            total+=flow*dist_arr[t];
    return total;
}
int main()
{
    read_value(n); read_value(m); read_value(k); read_value(v1); read_value(v2);
    t=IDX(n,110)+1;
    for(int i=2;i<=110;++i) insert_edge(IDX(1,i),t,INF_VAL,0);
    for(int i=2;i<=n;++i)
        for(int j=1;j<110;++j)
            insert_edge(IDX(i,j),IDX(i,j+1),INF_VAL,v1);
    for(int i=1,x;i<=k;++i) {read_value(x); insert_edge(s,IDX(x,1),1,0);}
    for(int i=1;i<=m;++i)
    {
        int x,y;
        read_value(x); read_value(y);
        for(int j=1;j<110;++j)
            for(int l=1;l<=k;++l)
                insert_edge(IDX(x,j),IDX(y,j+1),1,v2*(2*l-1)+v1),
                insert_edge(IDX(y,j),IDX(x,j+1),1,v2*(2*l-1)+v1);
    }
    printf("%d",min_cost_flow());
    return 0;
}
